global_custom_code.loader_start:
static uint32_t g_profileDomain;

static const char* g_profileFunctionList[] = {
    "__cu_demangle",
};

enum cufiltProfileCallbackId {
    cufilt_TRACE_CBID___cu_demangle = 0,
};

typedef uint32_t (*cufiltRegisterProfileDomain)(const char* domain_name, const char** function_list, uint32_t function_number);
typedef uint8_t (*cufiltIsProfileCallbackEnabled)(uint32_t domain, uint32_t callback_id);
typedef void (*cufiltProfileCallbackBegin)(uint32_t domain, uint32_t callback_id);
typedef void (*cufiltProfileCallbackEnd)(uint32_t domain, uint32_t callback_id);

struct cufiltProfileHandler {
    cufiltRegisterProfileDomain registerProfileDomain;
    cufiltIsProfileCallbackEnabled isCallbackEnabled;
    cufiltProfileCallbackBegin profileCallbackBegin;
    cufiltProfileCallbackEnd profileCallbackEnd;
};

static cufiltProfileHandler g_profileHandler;
static bool gDirectReturn = false;
static const char* gLibName = "cufilt";

static void InitializeProfileHandler() {
    // get library patch
    const char* profile_tool_library = getenv("WRAPPER_INJECTION_PATH");
    if (profile_tool_library == NULL) {
        return;
    }

    // open profile library
    void* tool_handler = dlopen(profile_tool_library, RTLD_LAZY);
    if (!tool_handler) {
        printf("cannot open the file:%s  with error %s\n", profile_tool_library, dlerror());
        return;
    }

    // init profile handler
    g_profileHandler.registerProfileDomain = reinterpret_cast<cufiltRegisterProfileDomain>(dlsym(tool_handler, "wrapperRegisterProfileDomain"));
    g_profileHandler.isCallbackEnabled = reinterpret_cast<cufiltIsProfileCallbackEnabled>(dlsym(tool_handler, "wrapperIsProfileCallbackEnabled"));
    g_profileHandler.profileCallbackBegin = reinterpret_cast<cufiltProfileCallbackBegin>(dlsym(tool_handler, "wrapperProfileCallbackBegin"));
    g_profileHandler.profileCallbackEnd = reinterpret_cast<cufiltProfileCallbackEnd>(dlsym(tool_handler, "wrapperProfileCallbackEnd"));

    // register profile domain
    if (g_profileHandler.registerProfileDomain != NULL) {
        g_profileDomain = g_profileHandler.registerProfileDomain(gLibName, g_profileFunctionList, sizeof(g_profileFunctionList) / sizeof(g_profileFunctionList[0]));
        if (g_profileDomain == 0) {
            g_profileHandler.isCallbackEnabled = NULL;
        }
    }
}

global_custom_code.pre_wrapper_call:
bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
    g_profileHandler.isCallbackEnabled(g_profileDomain, cufilt_TRACE_CBID_$WRAPPER_FUNC_NAME) != 0;
if (needProfile) {
    g_profileHandler.profileCallbackBegin(g_profileDomain, cufilt_TRACE_CBID_$WRAPPER_FUNC_NAME);
}
